import { NodeSDK } from '@opentelemetry/sdk-node';
import { LangfuseSpanProcessor } from '@langfuse/otel';
import { LangfuseClient } from '@langfuse/client';
import { observe, updateActiveTrace, updateActiveObservation } from '@langfuse/tracing';

// 1. Khoi tao OpenTelemetry exporter bat dong bo gui ve cum Langfuse self-host
const spanProcessor = new LangfuseSpanProcessor({
  publicKey: process.env.LANGFUSE_PUBLIC_KEY!,
  secretKey: process.env.LANGFUSE_SECRET_KEY!,
  baseUrl: process.env.LANGFUSE_BASE_URL ?? 'http://langfuse-web:3000',
  exportMode: 'batched', // Luon dung batched tren production de giu do tre < 25ms
});

export const otelSdk = new NodeSDK({ spanProcessors: [spanProcessor] });
otelSdk.start();

const langfuse = new LangfuseClient();

interface AgentDispatchInput {
  tenantId: string;
  saasTier: 'starter' | 'growth' | 'enterprise';
  leadId: string;
  userMessage: string;
}

// 2. Ham lay Prompt tu Langfuse co fallback va cache client 60s
async function getProductionPrompt(name: string, vars: Record<string, string>) {
  const prompt = await langfuse.prompt.get(name, {
    label: 'production',
    cacheTtlSeconds: 60,
  });
  return {
    compiled: prompt.compile(vars),
    promptMeta: prompt,
  };
}

// 3. Boc toan bo luong Agent bang @langfuse/tracing observe() de tu tao cay span
export const runCskhAgentWithTelemetry = observe(
  async (input: AgentDispatchInput) => {
    updateActiveTrace({
      name: 'domation-cskh-zalobot-turn',
      userId: input.tenantId, // Map truc tiep Tenant vao userId de tinh Unit Economics
      sessionId: `lead-${input.leadId}`,
      tags: [input.saasTier, 'zalo-oa', 'rag-v2'],
      metadata: {
        tenantId: input.tenantId,
        saasTier: input.saasTier,
        channel: 'zalobot',
      },
    });

    const { compiled, promptMeta } = await getProductionPrompt('cskh-bds-pricing-rag', {
      tenant_name: input.tenantId,
      user_query: input.userMessage,
    });

    // Span con do rieng buoc truy xuat RAG / PostgreSQL RLS
    const ragContext = await retrieveTenantDocs(input.tenantId, input.userMessage);

    // Span con ghi nhan luot goi model kem lien ket phien ban prompt
    updateActiveObservation({
      model: 'gemini-3.8-flash',
      prompt: promptMeta,
      metadata: { retrievedChunks: ragContext.length },
    });

    const reply = await invokeModelGateway(compiled, ragContext);
    return reply;
  },
  { name: 'cskh-agent-orchestrator', asType: 'agent' }
);

async function retrieveTenantDocs(tenantId: string, query: string): Promise<string[]> {
  return [`[Tenant:${tenantId}] Bang gia phan khu cap nhat cho: ${query}`];
}

async function invokeModelGateway(systemPrompt: string, chunks: string[]): Promise<string> {
  return `Da doi chieu ${chunks.length} nguon tai lieu noi bo theo prompt do dai ${systemPrompt.length}.`;
}
